package com.nexusduo.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import java.util.*;
public class NetworkActivity extends Activity{
 int dp(float v){return(int)(v*getResources().getDisplayMetrics().density+.5f);} GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;} TextView tv(String s,int z,int c){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(c);return t;} Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(14);b.setAllCaps(false);b.setBackground(bg(Color.rgb(38,43,60),16));return b;}
 String caps(String n){switch(n){case"TikTok":return"✅ Site web intégré\n✅ Vidéos publiques / profils publics selon disponibilité\n↗ Certains contenus peuvent exiger TikTok";case"Instagram":return"✅ Site web intégré\n✅ Publications publiques lorsque Meta les autorise\n↗ Connexion ou certains contenus peuvent ouvrir Instagram";case"Facebook":return"✅ Site web intégré\n✅ Pages / publications publiques lorsque Facebook les autorise\n↗ Contenu privé : Facebook";case"Twitch":return"✅ Site web intégré\n✅ Streams, VOD et clips publics\n✅ Chat selon disponibilité";case"YouTube":return"✅ Site web intégré\n✅ Vidéos et playlists publiques\n✅ Lecture dans Nexus Duo";case"X":return"✅ Site web intégré\n✅ Publications / profils publics selon disponibilité";case"Pinterest":return"✅ Site web intégré\n✅ Pins / tableaux publics selon disponibilité";case"Reddit":return"✅ Site web intégré\n✅ Publications et communautés publiques";case"Threads":return"✅ Site web intégré\n✅ Liens publics selon disponibilité";case"LinkedIn":return"✅ Site web intégré\n↗ Plusieurs contenus exigent LinkedIn";case"Discord":return"✅ Discord Web intégré\n↗ Invitations / fonctions avancées peuvent ouvrir Discord";case"Snapchat":return"✅ Snapchat Web lorsque disponible\n↗ Fonctions principales souvent dans Snapchat";default:return"✅ Site web intégré\n↗ Ouverture externe disponible";}}
 boolean hostMatches(String n,String u){try{String h=Uri.parse(u).getHost();if(h==null)return false;h=h.toLowerCase();if(n.equals("TikTok"))return h.contains("tiktok.com");if(n.equals("Instagram"))return h.contains("instagram.com");if(n.equals("Facebook"))return h.contains("facebook.com")||h.contains("fb.watch");if(n.equals("X"))return h.equals("x.com")||h.endsWith("twitter.com");if(n.equals("Twitch"))return h.contains("twitch.tv");if(n.equals("YouTube"))return h.contains("youtube.com")||h.equals("youtu.be");if(n.equals("Snapchat"))return h.contains("snapchat.com");if(n.equals("Pinterest"))return h.contains("pinterest.")||h.equals("pin.it");if(n.equals("Reddit"))return h.contains("reddit.com")||h.equals("redd.it");if(n.equals("Threads"))return h.contains("threads.net");if(n.equals("LinkedIn"))return h.contains("linkedin.com");if(n.equals("Discord"))return h.contains("discord.com")||h.contains("discord.gg");}catch(Exception e){}return false;}
 void openInternal(String name,String url){Intent i=new Intent(this,BrowserActivity.class);i.putExtra("name",name);i.putExtra("url",url);startActivity(i);} void openExternal(String url){try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){Toast.makeText(this,"Impossible d’ouvrir ce lien",Toast.LENGTH_SHORT).show();}}
 @Override public void onCreate(Bundle b){super.onCreate(b);String name=getIntent().getStringExtra("name"),url=getIntent().getStringExtra("url");ScrollView sv=new ScrollView(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(18),dp(28),dp(18),dp(30));r.setBackgroundColor(Color.rgb(8,10,15));TextView back=tv("‹  Retour",16,Color.rgb(180,185,197));back.setPadding(0,0,0,dp(8));back.setOnClickListener(v->finish());r.addView(back,new LinearLayout.LayoutParams(-1,dp(42)));TextView title=tv(name,30,Color.WHITE);title.setTypeface(null,1);r.addView(title,new LinearLayout.LayoutParams(-1,dp(54)));TextView sub=tv("Choisissez comment utiliser ce réseau dans Nexus Duo.",14,Color.rgb(156,163,175));r.addView(sub,new LinearLayout.LayoutParams(-1,dp(50)));
 Button inside=btn("🌐  Ouvrir le site dans Nexus Duo");inside.setOnClickListener(v->openInternal(name,url));r.addView(inside,new LinearLayout.LayoutParams(-1,dp(56)));Space s1=new Space(this);r.addView(s1,new LinearLayout.LayoutParams(1,dp(10)));Button outside=btn("↗  Ouvrir dans l’app / navigateur officiel");outside.setOnClickListener(v->openExternal(url));r.addView(outside,new LinearLayout.LayoutParams(-1,dp(56)));
 TextView allowed=tv("CE QUI PEUT ÊTRE INTÉGRÉ",12,Color.rgb(124,92,252));allowed.setTypeface(null,1);allowed.setPadding(0,dp(24),0,dp(10));r.addView(allowed);TextView info=tv(caps(name),14,Color.rgb(220,223,230));info.setPadding(dp(16),dp(16),dp(16),dp(16));info.setBackground(bg(Color.rgb(21,25,37),18));r.addView(info,new LinearLayout.LayoutParams(-1,-2));
 TextView pasteTitle=tv("INTÉGRER UN LIEN PUBLIC",12,Color.rgb(124,92,252));pasteTitle.setTypeface(null,1);pasteTitle.setPadding(0,dp(24),0,dp(10));r.addView(pasteTitle);EditText e=new EditText(this);e.setHint("Collez ici un lien "+name);e.setHintTextColor(Color.rgb(120,126,140));e.setTextColor(Color.WHITE);e.setSingleLine(true);e.setPadding(dp(14),0,dp(14),0);e.setBackground(bg(Color.rgb(21,25,37),16));r.addView(e,new LinearLayout.LayoutParams(-1,dp(54)));Space s2=new Space(this);r.addView(s2,new LinearLayout.LayoutParams(1,dp(10)));Button embed=btn("＋  Vérifier et intégrer dans Nexus Duo");embed.setOnClickListener(v->{String u=e.getText().toString().trim();if(u.length()==0){Toast.makeText(this,"Collez d’abord un lien",Toast.LENGTH_SHORT).show();return;}if(!u.startsWith("http://")&&!u.startsWith("https://"))u="https://"+u;if(!hostMatches(name,u)){Toast.makeText(this,"Ce lien ne semble pas appartenir à "+name,Toast.LENGTH_LONG).show();return;}Toast.makeText(this,"Lien reconnu — ouverture intégrée",Toast.LENGTH_SHORT).show();openInternal(name+" • intégré",u);});r.addView(embed,new LinearLayout.LayoutParams(-1,dp(56)));TextView note=tv("Nexus Duo n’essaie pas de contourner les restrictions du réseau. Si le site bloque l’intégration, utilisez le bouton d’ouverture officielle.",12,Color.rgb(145,150,163));note.setPadding(0,dp(16),0,0);r.addView(note);sv.addView(r);setContentView(sv);}
}
